  const conflict = await bookingRepository.findConflictingBooking(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }

  return bookingRepository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

