import type { Booking } from '@prisma/client';
import { bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { durationMinutes, isBefore, parseInstant } from '../../shared/time.js';
import * as bookingRepository from './repository.js';
import * as roomRepository from '../rooms/repository.js';
import * as userRepository from '../users/repository.js';
import { BOOKING_CANCELLED } from './schema.js';
import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';

const MIN_DURATION_MINUTES = 30;
const MAX_DURATION_MINUTES = 480; // 8 hours

async function validateBookingRules(
  startsAt: Date,
  endsAt: Date,
  roomId: string,
  userId: string,
): Promise<void> {
  if (isBefore(startsAt, new Date())) {
    throw validationFailed('Booking start must be in the future');
  }

  if (!isBefore(startsAt, endsAt)) {
    throw validationFailed('Booking end must be after start');
  }

  const duration = durationMinutes(startsAt, endsAt);
  if (duration < MIN_DURATION_MINUTES || duration > MAX_DURATION_MINUTES) {
    throw validationFailed(
      `Booking duration must be between ${MIN_DURATION_MINUTES} minutes and ${Math.floor(MAX_DURATION_MINUTES / 60)} hours`,
      { duration, min: MIN_DURATION_MINUTES, max: MAX_DURATION_MINUTES },
    );
  }

  const room = await roomRepository.findById(roomId);
  if (!room) {
    throw notFound('Room');
  }

  const user = await userRepository.findById(userId);
  if (!user) {
    throw notFound('User');
  }
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const startsAt = parseInstant(input.startsAt);
  const endsAt = parseInstant(input.endsAt);

  await validateBookingRules(startsAt, endsAt, input.roomId, input.userId);

  const conflict = await bookingRepository.findConflictingBooking(input.roomId, startsAt, endsAt);
  if (conflict) {
    throw bookingConflict(conflict.id);
  }

  return bookingRepository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    startsAt,
    endsAt,
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await bookingRepository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await bookingRepository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const existing = await getBooking(id);

  const startsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : existing.startsAt;
  const endsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : existing.endsAt;
  const roomId = input.roomId !== undefined ? input.roomId : existing.roomId;
  const userId = input.userId !== undefined ? input.userId : existing.userId;

  if (input.startsAt !== undefined || input.endsAt !== undefined || input.roomId !== undefined || input.userId !== undefined) {
    await validateBookingRules(startsAt, endsAt, roomId, userId);

    const conflict = await bookingRepository.findConflictingBooking(roomId, startsAt, endsAt);
    if (conflict && conflict.id !== id) {
      throw bookingConflict(conflict.id);
    }
  }

  return bookingRepository.update(id, {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt: parseInstant(input.startsAt) } : {}),
    ...(input.endsAt !== undefined ? { endsAt: parseInstant(input.endsAt) } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}

